mapper.select:
SELECT customers.id AS organizationId, CONCAT_WS(' - ', customers.customer_code, customers.name) AS organizationName, currency_centers.symbol AS currencySymbol, orders.id AS soId, orders.type AS `type`, orders.order_code AS soNo, orders.order_date AS soDate, orders.is_close AS isClose, orders.is_approve AS isApprove, orders.status AS status, DATEDIFF(DATE(NOW()), orders.order_date) AS dateDiff, sales_orders.id AS invoiceId, sales_orders.so_code AS invoiceNo, CONCAT(users.last_name, ' ', users.first_name) AS createdBy, (orders.total_amount + orders.total_vat) AS totalAmount FROM orders INNER JOIN customers ON orders.customer_id = customers.id INNER JOIN users ON orders.created_by = users.id INNER JOIN currency_centers ON currency_centers.id = orders.currency_center_id LEFT JOIN sales_orders ON orders.id = sales_orders.order_id AND sales_orders.status > 0 WHERE orders.status > 0
AND orders.order_date >= #{filter.dateFrom}
AND orders.order_date <= #{filter.dateTo}
AND orders.customer_id = #{filter.organizationId}
AND orders.type = #{filter.type}
ORDER BY organizationName, orders.order_code ASC
LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT COUNT(DISTINCT customers.id)
FROM orders
INNER JOIN customers ON orders.customer_id = customers.id
INNER JOIN users ON orders.created_by = users.id
INNER JOIN currency_centers ON currency_centers.id = orders.currency_center_id
LEFT JOIN sales_orders ON orders.id = sales_orders.order_id AND sales_orders.status > 0
WHERE orders.status > 0

    AND orders.order_date >= #{filter.dateFrom}


    AND orders.order_date <= #{filter.dateTo}


    AND orders.customer_id = #{filter.organizationId}


    AND orders.type = #{filter.type}
